package com.secureshop.app.service; import java.util.*; import org.springframework.stereotype.*; import com.secureshop.app.model.*; @Service public class ProductService { private final List<Product> p=List.of(new Product(1L,"Secure Laptop",1299.99),new Product(2L,"Cloud Keyboard",89.99)); public List<Product> all(){return p;} public Product byId(Long id){return p.stream().filter(x->x.id().equals(id)).findFirst().orElseThrow(()->new IllegalArgumentException("Product not found"));} }
